window.addEventListener('error',e=>{try{const msg=String(e?.error?.message||e?.message||'Frontend startup error');let el=document.getElementById('myai-boot-error');if(!el){el=document.createElement('div');el.id='myai-boot-error';el.style.cssText='position:fixed;inset:20px;z-index:99999;background:#fff;color:#111;padding:24px;border:2px solid #b42318;border-radius:14px;font:14px/1.6 system-ui,sans-serif;box-shadow:0 20px 60px rgba(0,0,0,.3)';document.body.appendChild(el);}el.innerHTML='<h2 style="margin:0 0 8px">MYAI CFO frontend startup error</h2><p style="margin:0 0 12px">The local kernel is running but the UI encountered a startup error.</p><pre style="white-space:pre-wrap">'+msg.replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))+'</pre><button onclick="location.reload()" style="padding:9px 14px">Reload</button>';}catch{}});
const API=(()=>{try{const q=new URLSearchParams(window.location.search).get('apiBase');if(q){const clean=q.replace(/\/$/,'');return clean.endsWith('/api')?clean:`${clean}/api`;}if(window.__MYAI_API_BASE__){const clean=String(window.__MYAI_API_BASE__).replace(/\/$/,'');return clean.endsWith('/api')?clean:`${clean}/api`;}}catch{}return 'http://127.0.0.1:47821/api';})();
async function fetchJsonWithRetry(path,options={},retries=2){let lastError=null;for(let attempt=0;attempt<=retries;attempt++){try{const response=await fetch(API+path,{...options,signal:options.signal||AbortSignal.timeout(30000)});const text=await response.text();let body={};try{body=JSON.parse(text)}catch{body={raw:text}};if(!response.ok){const err=new Error(body.error||body.detail||`HTTP ${response.status}`);err.httpStatus=response.status;err.body=body;throw err;}return {response,body};}catch(e){lastError=e;if(attempt<retries)await new Promise(r=>setTimeout(r,600*(attempt+1)));}}throw lastError||new Error('Local API request failed');}
function auditClientEvent(eventType,payload={}){fetch(API+'/audit/client-event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({eventType,payload})}).catch(()=>{});}
