    {tab==='copilot'&&<Copilot {...copilot} ask={(e,scope)=>copilot.ask(e,scope)} company={company} companies={companies} activeCompanyId={active}/>}
    {tab==='pa'&&<CfoPA {...pa} ask={(e,scope)=>pa.ask(e,scope)} />}
    {tab==='arena'&&<Arena/>}
    {tab==='models'&&<Models/>}
    {tab==='knowledge'&&<Knowledge/>}
    {tab==='documents'&&<Documents company={company} companies={companies} reload={load}/>} 
    {tab==='worldtime'&&<WorldTime/>}
