function AnalogClock({now,tz}){
 const parts=new Intl.DateTimeFormat('en-GB',{timeZone:tz,hour:'numeric',minute:'numeric',second:'numeric',hour12:false}).formatToParts(now); const get=k=>Number(parts.find(x=>x.type===k)?.value||0); const h=get('hour')%12,m=get('minute'),s=get('second');
 return <div className="analog-clock"><div className="clock-hand hour" style={{transform:`rotate(${h*30+m*.5}deg)`}}/><div className="clock-hand minute" style={{transform:`rotate(${m*6+s*.1}deg)`}}/><div className="clock-hand second" style={{transform:`rotate(${s*6}deg)`}}/><i/></div>
}


